-- 0056_team_store_orders.sql
-- MON-15 (UC-25, UC-26): orders from the team store. Two new tables, no
-- change to existing ones. Money stays on the linked invoice (paid on the
-- player's Payments page); these rows carry what was ordered (name and
-- price as ordered, size, name and number on the back, backorder) and the
-- fulfilment state. Generated by drizzle-kit, numbered after 0055.
-- Idempotent: CREATE ... IF NOT EXISTS and guarded constraints.

CREATE TABLE IF NOT EXISTS "team_store_order_items" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"order_id" uuid NOT NULL,
	"product_id" uuid,
	"product_name" text NOT NULL,
	"unit_price_cents" integer NOT NULL,
	"quantity" integer NOT NULL,
	"size" text,
	"personal_name" text,
	"personal_number" integer,
	"backorder" boolean DEFAULT false NOT NULL,
	"reserved_qty" integer DEFAULT 0 NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "team_store_order_item_qty_check" CHECK ("team_store_order_items"."quantity" BETWEEN 1 AND 10),
	CONSTRAINT "team_store_order_item_number_check" CHECK ("team_store_order_items"."personal_number" IS NULL OR "team_store_order_items"."personal_number" BETWEEN 0 AND 99),
	CONSTRAINT "team_store_order_item_price_check" CHECK ("team_store_order_items"."unit_price_cents" >= 0)
);
--> statement-breakpoint
CREATE TABLE IF NOT EXISTS "team_store_orders" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"org_id" uuid NOT NULL,
	"team_id" uuid NOT NULL,
	"buyer_person_id" uuid NOT NULL,
	"invoice_id" uuid,
	"status" text DEFAULT 'placed' NOT NULL,
	"total_cents" integer NOT NULL,
	"currency" text DEFAULT 'USD' NOT NULL,
	"note" text,
	"status_changed_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "team_store_order_status_check" CHECK ("team_store_orders"."status" IN ('placed','processing','shipped','cancelled')),
	CONSTRAINT "team_store_order_total_check" CHECK ("team_store_orders"."total_cents" >= 0)
);
